<?php
namespace App\Services\Dapcode; use Illuminate\Support\Facades\File; use Illuminate\Support\Str; class SourceMapVaultService { protected static $vaultPath; public static function getVaultPath() { if ( ! static ::$vaultPath) { static ::$vaultPath = storage_path('app/dapcode/.sourcemaps'); } if ( ! File::isDirectory( static ::$vaultPath)) { File::makeDirectory( static ::$vaultPath, 0700, true, true); } return static ::$vaultPath; } public static function normalizeRelativePath(string $filePath) : string { $normalizedFile = str_replace('\\', '/', $filePath); $normalizedBase = str_replace('\\', '/', base_path()); if (stripos($normalizedFile, $normalizedBase) === 0) { return ltrim(substr($normalizedFile, strlen($normalizedBase)), '/'); } return ltrim($normalizedFile, '/'); } public static function getVaultKey($filePath) { $relPath = static ::normalizeRelativePath($filePath); return md5($relPath) . '.dapmap'; } public static function getLegacyVaultKey($filePath) { $relPath = str_replace('\\', '/', Str::after($filePath, base_path() . DIRECTORY_SEPARATOR)); return md5($relPath) . '.dapmap'; } public static function storeMap($filePath, $originalContent, $minifiedContent) { $vaultDir = static ::getVaultPath(); $vaultKey = static ::getVaultKey($filePath); $vaultFile = $vaultDir . DIRECTORY_SEPARATOR . $vaultKey; $lines = substr_count($originalContent, "\n") + 1; $isOriginal = ($lines > 2) || strlen($originalContent) < 100; if (File::isFile($vaultFile) && ! $isOriginal) { return true; } $relPath = static ::normalizeRelativePath($filePath); $instId = InstallationService::getInstallationId(); $compressed = gzdeflate($originalContent, 9); $encodedPayload = base64_encode($compressed !== false ? $compressed : $originalContent); $data = [ 'file' => $relPath, 'orig_hash' => hash('sha256', $originalContent), 'mini_hash' => hash('sha256', $minifiedContent), 'inst_id' => $instId, 'created_at' => time(), 'payload' => $encodedPayload, 'checksum' => hash_hmac('sha256', $encodedPayload, $instId . '|DAPCODE-SOURCEMAP-V1'), ]; $json = json_encode($data); File::put($vaultFile, $json); @chmod($vaultFile, 0600); return true; } public static function hasMap($filePath) { $vaultDir = static ::getVaultPath(); $primary = $vaultDir . DIRECTORY_SEPARATOR . static ::getVaultKey($filePath); if (File::isFile($primary)) { return true; } $legacy = $vaultDir . DIRECTORY_SEPARATOR . static ::getLegacyVaultKey($filePath); return File::isFile($legacy); } public static function getVaultMapData(string $filePath) : ? array { $vaultDir = static ::getVaultPath(); $primary = $vaultDir . DIRECTORY_SEPARATOR . static ::getVaultKey($filePath); $vaultFile = null; if (File::isFile($primary)) { $vaultFile = $primary; } else { $legacy = $vaultDir . DIRECTORY_SEPARATOR . static ::getLegacyVaultKey($filePath); if (File::isFile($legacy)) { $vaultFile = $legacy; } } if ( ! $vaultFile) { return null; } $json = File::get($vaultFile); $data = @json_decode($json, true); if ( ! is_array($data) || empty($data['payload'])) { return null; } $instId = InstallationService::getInstallationId(); $expectedChecksum = hash_hmac('sha256', $data['payload'], $instId . '|DAPCODE-SOURCEMAP-V1'); if ( ! hash_equals($expectedChecksum, (string) ($data['checksum'] ?? ''))) { return null; } if ($vaultFile !== $primary) { @File::put($primary, $json); @chmod($primary, 0600); } return $data; } public static function verifyMinifiedFile(string $filePath, string $expectedOrigHash) : bool { if ( ! File::isFile($filePath)) { return false; } $mapData = static ::getVaultMapData($filePath); if ( ! $mapData) { return false; } if ( ! isset($mapData['orig_hash']) || ! hash_equals($expectedOrigHash, (string) $mapData['orig_hash'])) { return false; } if ( ! isset($mapData['mini_hash'])) { return false; } $currentFileHash = hash_file('sha256', $filePath); if ( ! hash_equals((string) $mapData['mini_hash'], $currentFileHash)) { return false; } $content = File::get($filePath); if ( ! ModuleEncryptionService::validatePhpSyntax($content)) { return false; } return true; } public static function restoreOriginal($filePath) { $mapData = static ::getVaultMapData($filePath); if ( ! $mapData) { return null; } $decoded = base64_decode($mapData['payload']); $uncompressed = @gzinflate($decoded); return $uncompressed !== false ? $uncompressed : $decoded; } public static function cleanMap($filePath) { $vaultDir = static ::getVaultPath(); $primary = $vaultDir . DIRECTORY_SEPARATOR . static ::getVaultKey($filePath); $legacy = $vaultDir . DIRECTORY_SEPARATOR . static ::getLegacyVaultKey($filePath); $deleted = false; if (File::isFile($primary)) { $deleted = File::delete($primary) || $deleted; } if (File::isFile($legacy)) { $deleted = File::delete($legacy) || $deleted; } return $deleted; } public static function cleanAllMaps() { $vaultDir = static ::getVaultPath(); $count = 0; if (File::isDirectory($vaultDir)) { foreach (File::files($vaultDir) as $file) { if ($file->getExtension() === 'dapmap') { File::delete($file->getRealPath()); $count++; } } } return $count; } }